<script setup>
import { computed, ref, onMounted, onUnmounted } from 'vue'
import { Plus, Search, Pencil, Trash2, X, Users, Phone, IdCard, Check } from 'lucide-vue-next'
import { readData, updateData, uid, addActivity } from '../services/storage'
function blank(){return {name:'',phone:'',license:'',status:'Available'}}
const tick=ref(0), search=ref(''), modal=ref(false), editing=ref(null), error=ref(''), success=ref(''), form=ref(blank())
const saving = ref(false)
const data=computed(()=>{tick.value;return readData()})
const rows=computed(()=>data.value.drivers.filter(d=>[d.name,d.phone,d.license].some(v=>String(v).toLowerCase().includes(search.value.toLowerCase()))))
const refresh=()=>tick.value++
onMounted(()=>window.addEventListener('taxigo:data-updated',refresh));onUnmounted(()=>window.removeEventListener('taxigo:data-updated',refresh))
function open(d){editing.value=d?.id||null;form.value=d?{...d}:blank();error.value='';modal.value=true}
function save(){error.value='';if(saving.value)return;saving.value=true;if(form.value.name.trim().length<2){error.value='Enter the driver’s full name.';saving.value=false;return}if(!/^[0-9+()\-\s]{7,20}$/.test(form.value.phone.trim())){error.value='Enter a valid phone number.';saving.value=false;return}if(form.value.license.trim().length<5){error.value='Enter a valid license number.';saving.value=false;return}const duplicate=data.value.drivers.some(d=>d.license.toLowerCase()===form.value.license.trim().toLowerCase()&&d.id!==editing.value);if(duplicate){error.value='That license number already exists.';saving.value=false;return}updateData(d=>{if(editing.value){const old=d.drivers.find(x=>x.id===editing.value);Object.assign(old,form.value,{name:form.value.name.trim(),phone:form.value.phone.trim(),license:form.value.license.trim()})}else d.drivers.unshift({...form.value,id:uid('driver'),name:form.value.name.trim(),phone:form.value.phone.trim(),license:form.value.license.trim(),createdAt:new Date().toISOString()})});addActivity(`${editing.value?'Updated':'Added'} driver ${form.value.name}`);modal.value=false;success.value='Driver record saved.';saving.value=false}
function remove(d){if(data.value.bookings.some(b=>['Confirmed','In Progress'].includes(b.status)&&b.driverId===d.id)){error.value='This driver is assigned to an active ride. Complete or cancel that ride first.';return}if(!confirm(`Remove ${d.name} from the driver list?`))return;updateData(x=>{x.drivers=x.drivers.filter(v=>v.id!==d.id)});success.value='Driver removed.';error.value=''}
</script>
<template><div class="page-heading"><div><div class="eyebrow">FLEET OPERATIONS</div><h1>Driver management</h1><p>Maintain driver profiles and track operational availability.</p></div><button class="btn btn-primary" @click="open()"><Plus :size="17"/> Add driver</button></div><div v-if="success" class="alert alert-success">{{success}}<button @click="success=''"><X :size="16"/></button></div><div v-if="error&&!modal" class="alert alert-error">{{error}}<button @click="error=''"><X :size="16"/></button></div><div class="mini-stats"><div class="mini-stat"><span>Total drivers</span><strong>{{data.drivers.length}}</strong></div><div class="mini-stat"><span>Available</span><strong class="text-green">{{data.drivers.filter(d=>d.status==='Available').length}}</strong></div><div class="mini-stat"><span>On active ride</span><strong class="text-blue">{{data.bookings.filter(b=>b.status==='In Progress'&&b.driverId).length}}</strong></div><div class="mini-stat"><span>Inactive</span><strong class="text-amber">{{data.drivers.filter(d=>d.status==='Inactive').length}}</strong></div></div><div class="list-toolbar"><div class="search-field"><Search :size="17"/><input v-model="search" placeholder="Search name, phone or license…"/></div><span class="results-count">{{rows.length}} drivers</span></div><div class="driver-grid"><article v-for="d in rows" :key="d.id" class="driver-card"><div class="driver-card-top"><div class="driver-avatar large">{{d.name.split(' ').map(s=>s[0]).slice(0,2).join('')}}</div><span class="status-pill" :class="d.status.toLowerCase()">{{d.status}}</span></div><h3>{{d.name}}</h3><p class="driver-role">Taxi driver</p><div class="driver-info"><div><Phone :size="15"/><span>{{d.phone}}</span></div><div><IdCard :size="15"/><span>{{d.license}}</span></div></div><div class="driver-card-footer"><span>Added {{new Date(d.createdAt).toLocaleDateString()}}</span><div class="action-row"><button class="mini-action" @click="open(d)" title="Edit driver"><Pencil :size="15"/></button><button class="mini-action danger-action" @click="remove(d)" title="Remove driver"><Trash2 :size="15"/></button></div></div></article><div v-if="!rows.length" class="empty-state grid-empty"><Users :size="32"/><strong>No drivers found</strong><p>Add a driver or change your search.</p></div></div><div v-if="modal" class="modal-backdrop" @click.self="modal=false"><section class="modal-card"><div class="modal-heading"><div><div class="eyebrow">FLEET DIRECTORY</div><h2>{{editing?'Edit driver':'Add a driver'}}</h2><p class="muted">Keep driver contact and license records up to date.</p></div><button class="icon-button" @click="modal=false"><X/></button></div><form class="form-stack" @submit.prevent="save"><label>Full name<input v-model.trim="form.name" required minlength="2" maxlength="100" placeholder="Driver's full name"/></label><div class="form-grid"><label>Contact number<input v-model.trim="form.phone" required placeholder="09XX XXX XXXX"/></label><label>License number<input v-model.trim="form.license" required minlength="5" placeholder="Driver license ID"/></label></div><label>Status<select v-model="form.status"><option>Available</option><option>Inactive</option></select></label><p v-if="error" class="form-error">{{error}}</p><div class="modal-actions"><button type="button" class="btn btn-secondary" @click="modal=false">Cancel</button><button class="btn btn-primary" type="submit" :disabled="saving"><Check :size="16"/> {{ saving ? 'Saving…' : 'Save driver' }}</button></div></form></section></div></template>